CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Block-level warp-shuffle + shared-memory reduction kernel
// Each block processes a contiguous chunk via a grid-stride loop,
// accumulates partial Huber sums, then reduces to one value per block.

#define BLOCK_SIZE 256

__device__ __forceinline__ float huber_elem(float pred, float tgt) {
    float d = pred - tgt;
    float ad = fabsf(d);
    return (ad < 1.0f) ? (0.5f * d * d) : (ad - 0.5f);
}

// Pass-1 kernel: grid-stride, float4 vectorized loads when possible,
// warp shuffle + shared-mem block reduction -> one partial per block.
__global__ void huber_partial_sum_kernel(
    const float* __restrict__ pred,
    const float* __restrict__ tgt,
    float* __restrict__ partials,
    int n4,   // number of float4 groups
    int n     // total elements
) {
    float acc = 0.0f;
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    // Vectorized float4 pass
    const float4* pred4 = reinterpret_cast<const float4*>(pred);
    const float4* tgt4  = reinterpret_cast<const float4*>(tgt);
    for (int i = tid; i < n4; i += stride) {
        float4 p = pred4[i];
        float4 t = tgt4[i];
        acc += huber_elem(p.x, t.x);
        acc += huber_elem(p.y, t.y);
        acc += huber_elem(p.z, t.z);
        acc += huber_elem(p.w, t.w);
    }
    // Tail elements
    int tail_start = n4 * 4;
    for (int i = tail_start + tid; i < n; i += stride) {
        acc += huber_elem(pred[i], tgt[i]);
    }

    // Warp-level reduction
    unsigned mask = 0xffffffff;
    acc += __shfl_down_sync(mask, acc, 16);
    acc += __shfl_down_sync(mask, acc,  8);
    acc += __shfl_down_sync(mask, acc,  4);
    acc += __shfl_down_sync(mask, acc,  2);
    acc += __shfl_down_sync(mask, acc,  1);

    __shared__ float smem[BLOCK_SIZE / 32];
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    if (lane == 0) smem[warp] = acc;
    __syncthreads();

    // Final block reduction in first warp
    if (warp == 0) {
        acc = (lane < (BLOCK_SIZE / 32)) ? smem[lane] : 0.0f;
        acc += __shfl_down_sync(mask, acc, 4);
        acc += __shfl_down_sync(mask, acc, 2);
        acc += __shfl_down_sync(mask, acc, 1);
        if (lane == 0) partials[blockIdx.x] = acc;
    }
}

// Pass-2 kernel: single block reduces the partials array and divides by N.
__global__ void huber_final_reduce_kernel(
    const float* __restrict__ partials,
    float* __restrict__ output,
    int num_partials,
    float inv_n
) {
    float acc = 0.0f;
    for (int i = threadIdx.x; i < num_partials; i += blockDim.x) {
        acc += partials[i];
    }
    unsigned mask = 0xffffffff;
    acc += __shfl_down_sync(mask, acc, 16);
    acc += __shfl_down_sync(mask, acc,  8);
    acc += __shfl_down_sync(mask, acc,  4);
    acc += __shfl_down_sync(mask, acc,  2);
    acc += __shfl_down_sync(mask, acc,  1);
    if (threadIdx.x == 0) {
        output[0] = acc * inv_n;
    }
}

torch::Tensor huber_loss_forward_cuda(torch::Tensor predictions, torch::Tensor targets) {
    int n = (int)predictions.numel();
    int n4 = n / 4;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    int blocks = (n + BLOCK_SIZE * 4 - 1) / (BLOCK_SIZE * 4);
    blocks = min(blocks, 2048);

    auto partials = torch::empty({blocks}, predictions.options());
    auto output   = torch::empty({1}, predictions.options());

    huber_partial_sum_kernel<<<blocks, BLOCK_SIZE, 0, stream>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        partials.data_ptr<float>(),
        n4, n
    );

    int final_block = min(blocks, 256);
    huber_final_reduce_kernel<<<1, final_block, 0, stream>>>(
        partials.data_ptr<float>(),
        output.data_ptr<float>(),
        blocks,
        1.0f / (float)n
    );

    return output[0];
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that computes Smooth L1 (Huber) Loss for regression tasks.

        Parameters:
            None
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, predictions, targets):
        # <<<IMPROVE:forward_stmt_1>>>
        if (predictions.is_cuda and targets.is_cuda and
                predictions.is_contiguous() and targets.is_contiguous() and
                predictions.sizes() == targets.sizes() and
                predictions.dtype == torch.float32 and targets.dtype == torch.float32):
            return _stark_get_extension().huber_loss_forward(predictions, targets)
        return torch.nn.functional.smooth_l1_loss(predictions, targets)
        # <<<END_IMPROVE>>>

